import{z as i,x as c,o,c as n,q as E,j as t,D as a,d as s,s as d,S as l}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"动态分派与虚表","description":"","frontmatter":{"title":"动态分派与虚表","date":"2026-09-10T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/vtable-preview.md","filePath":"cs/vtable-preview.md","lastUpdated":1791063341000}'),p={name:"cs/vtable-preview.md"};function A(B,e,_,h,m,T){const r=c("Mermaid");return o(),n("div",null,[e[2]||(e[2]=E('<h1 id="动态分派与虚表" tabindex="-1">动态分派与虚表 <a class="header-anchor" href="#动态分派与虚表" aria-label="Permalink to &quot;动态分派与虚表&quot;">​</a></h1><div class="epigraph"><p>调用哪一份实现，可以等到运行时看对象里的函数表指针；那张表把同一套操作名映到不同代码地址。</p><footer>—— 据 Bryant and O&#39;Hallaron, Computer Systems: A Programmer&#39;s Perspective；ISO/IEC 9899 整理</footer></div><p>上一课<a href="/cs/encapsulation-invariant">封装与不变量</a>把表示藏进实现文件，公开函数维持不变量。本课不重讲不完整类型，也不从 Java 接口教程另起。缺口是：有时调用方只拿着「满足某契约的对象」，<strong>具体哪一种表示要到运行时才知道</strong>。静态函数名不够用，需要按对象选择函数指针。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>函数指针已经能把代码地址当值传。动态分派是把一组函数指针捆在对象上：每个对象带一张表（或指向共享表的指针），调用 <code>obj-&gt;ops-&gt;draw(obj)</code> 时，跳转目标来自该对象的表，而不是来自源码里写死的函数名。缺口因此不是「多态」词汇，而是<strong>一次间接：先读表，再 call</strong>。调用约定仍适用，只是 callee 地址从对象里取出。</p><p>C 里这是显式的。C++ 虚函数把同样的布局藏进编译器：对象前部一个虚表指针，调用编成一次间接。本课用 C 的显式表建立机器直觉，不把语言特性清单当内容。多种表示仍各有自己的不变量；表只保证操作名对齐，不自动合并不变量。</p><h3 id="虚表不是「继承」" tabindex="-1">虚表不是「继承」 <a class="header-anchor" href="#虚表不是「继承」" aria-label="Permalink to &quot;虚表不是「继承」&quot;">​</a></h3><p>子类型、实现复用、字段布局兼容是更后的问题。本课只需要：同一组函数签名，多份实现，对象里有办法找到该用哪一份。没有「父类字段排在前面」的要求。把虚表等同于继承树，会把 C 里常见的驱动函数表、操作系统的文件操作向量讲歪。</p><p><span class="marginnote">CSAPP 在机器级说明间接调用：目标在寄存器或内存里，而不是在指令的立即数里。ISO C 保证函数指针可以调用，只要类型兼容。本课不把 Itanium ABI 的虚表细节当主干。</span></p><p><span class="marginnote">「一次间接」翻译成大白话：普通调用的目标地址在编译时就焊进指令；动态分派的地址要先从对象里读出来再跳——多读一次内存，换来运行时换实现的自由。初学者容易把这张表当成继承的产物；C 里没有继承也有操作向量，表对齐的是函数签名，不是类层次。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>定义一组函数指针的结构体作为「操作表」。每种实现提供一份静态常量表，创建对象时写入 <code>ops</code> 指针。调用方只看见不完整对象加操作表。销毁也走表，以免调用方知道该 <code>free</code> 哪些附属块——所有权仍在封装里。</p>',12)),(o(),t(l,null,{default:a(()=>[d(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20OBJ%5B%22%E5%AF%B9%E8%B1%A1%22%5D%20--%3E%20VPTR%5B%22%E6%8C%87%E5%90%91%E6%93%8D%E4%BD%9C%E8%A1%A8%22%5D%0A%20%20VPTR%20--%3E%20T%5B%22%E8%A1%A8%EF%BC%9A%E5%87%BD%E6%95%B0%E6%8C%87%E9%92%88%E4%BB%AC%22%5D%0A%20%20T%20--%3E%20IMPL%5B%22%E6%9F%90%E4%B8%80%E7%A7%8D%E5%AE%9E%E7%8E%B0%E7%9A%84%E4%BB%A3%E7%A0%81%22%5D%0A%20%20CALL%5B%22%E9%97%B4%E6%8E%A5%E8%B0%83%E7%94%A8%22%5D%20--%3E%20T%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=E('<p><span class="marginnote">直觉类比：对象是插座，<code>ops</code> 表是面板上插孔的排布约定——任何实现只要孔位对齐（<code>read</code>/<code>write</code>/<code>close</code> 签名一致）就能插上去，孔后面接什么电路随意。这就是操作系统文件、套接字共用一张操作向量的原因。</span></p><p>表通常共享：同类对象指向同一张静态表，节省每个实例一份函数指针。对象差异放在表后面的私有数据。不要每对象复制整张表，除非真要在运行时改单个方法。</p><p>表指针本身是对象的一部分，拷贝对象若只拷数据不拷 <code>ops</code>，或浅拷后两对象共享可变私有缓冲，所有权会乱。深拷要决定表是否共享（通常共享静态表）以及私有数据是否新分配。这与 RAII 即将出现的「谁销毁附属块」是同一问题的前半。C++ 编译器把虚表指针藏在对象开头，布局因此多一个指针宽度的偏移——本课用显式字段避免把这当成魔法。不要在构造完成前调用表项：那时 <code>ops</code> 可能还是空，间接调用即 UB。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>间接调用让分支预测与内联变难：编译器在看不到确定目标时不能把 callee 嵌进来。这是封装可替换性在性能上的税，不是 bug。调试时断点要打在实现函数上，或在间接调用处看表指针指向哪张表。后课动态链接会再出现一次间接（过程链接表）；机制同类，对象换成共享库。</p><p>安全上，若对象内存被破坏导致 <code>ops</code> 被改写，间接调用会跳到任意地址。封装与寿命课在此继续有效：活对象、合法表、类型匹配的函数指针。</p><p>操作系统里文件、套接字、设备常用同一张「操作向量」：<code>read</code>/<code>write</code>/<code>close</code> 名字对齐，对象里的私有数据各异。这就是本课的表，与语言是否支持 <code>class</code> 无关。调用约定仍然适用：间接调用也要按 ABI 放参数，只是目标地址来自内存。调试时若表指针被踩，回溯会跳进垃圾地址，症状像栈破坏，根子是对象寿命或缓冲溢出——悬挂课在此以另一种形式出现。后课 RAII 要求销毁也走表，以免调用方为每种表示写一份 <code>free</code>。</p>',7)),(o(),t(l,null,{default:a(()=>[d(r,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20NEW%5B%22%E5%88%9B%E5%BB%BA%E5%AF%B9%E8%B1%A1%22%5D%20--%3E%20SET%5B%22%E6%9E%84%E9%80%A0%E6%97%B6%E5%86%99%E5%85%A5%20ops%20%E6%8C%87%E9%92%88%22%5D%0A%20%20SET%20--%3E%20USE%5B%22%E8%B0%83%E7%94%A8%E4%B8%8E%E9%87%8A%E6%94%BE%E9%83%BD%E7%BB%8F%E8%A1%A8%22%5D%0A%20%20USE%20--%3E%20DESTROY%5B%22%E9%94%80%E6%AF%81%E6%97%B6%E7%BB%8F%E8%A1%A8%E8%B0%83%20close%2Ffree%22%5D%0A%20%20DESTROY%20--%3E%20CLEAN%5B%22%E9%87%8A%E6%94%BE%E8%A1%A8%E8%83%8C%E5%90%8E%E7%9A%84%E9%99%84%E5%B1%9E%E7%A7%81%E6%9C%89%E6%95%B0%E6%8D%AE%22%5D%0A%20%20CLEAN%20--%3E%20DONE%5B%22%E8%B0%83%E7%94%A8%E6%96%B9%E4%B8%8D%E5%BF%85%E7%9F%A5%E9%81%93%E5%86%85%E6%83%85%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[s(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=E('<p><span class="marginnote">常见误区：以为这张表只是「调方法用」。它同时是所有权合同——销毁走表、释放附属块走表，调用方才不必为每种实现各写一份清理代码；构造完成前调用表项则是 UB，因为 <code>ops</code> 可能还是空的。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲多重继承的多张表，不把 RTTI 请来。下一课<a href="/cs/raii">资源获取即初始化</a>把销毁从「记得调表项」绑回对象寿命。后课默认：可替换实现用对象上的函数表做一次间接调用；不变量仍由各实现自己维持。</p><p>操作表应在对象活着期间保持不变，除非契约明确允许动态替换方法。中途改 <code>ops</code> 等于改类型，已进行的调用可能看见两半实现。销毁后表指针与数据指针同等悬挂。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>动态分派是对象上的函数表加一次间接调用。</li><li>表对齐的是操作签名，不是继承树。</li><li>同类对象共享静态表；私有数据跟在对象里。</li><li>下一课把资源释放绑到对象结束寿命之时。</li><li>出处：CSAPP 间接调用；ISO C 函数指针；C 里显式操作表的惯例。</li></ul>',6))])}const f=i(p,[["render",A]]);export{u as __pageData,f as default};
